// Some portions generated by Codex
package org.eclipse.rdf4j.workbench.security;

import static org.assertj.core.api.Assertions.assertThat;

import java.lang.reflect.Method;
import java.util.function.Supplier;

import org.eclipse.rdf4j.workbench.proxy.WorkbenchServlet;
import org.junit.jupiter.api.Test;

class WorkbenchSessionStateSecurityTest {

	@Test
	void isolatesManagersBySessionAndClosesThemOnCredentialChangeAndExpiry() throws Exception {
		Object aliceSession = newState();
		Object bobSession = newState();
		RecordingServlet alice = new RecordingServlet();
		RecordingServlet bob = new RecordingServlet();
		Method get = aliceSession.getClass()
				.getMethod("workbenchServlet", String.class, String.class, String.class, Supplier.class);

		Object aliceResult = get.invoke(aliceSession, "https://example.org/server", "alice", "a-secret",
				(Supplier<WorkbenchServlet>) () -> alice);
		Object bobResult = get.invoke(bobSession, "https://example.org/server", "bob", "b-secret",
				(Supplier<WorkbenchServlet>) () -> bob);
		assertThat(aliceResult).isSameAs(alice).isNotSameAs(bobResult);

		RecordingServlet replacement = new RecordingServlet();
		Object replacementResult = get.invoke(aliceSession, "https://example.org/server", "alice", "new-secret",
				(Supplier<WorkbenchServlet>) () -> replacement);
		assertThat(replacementResult).isSameAs(replacement);
		assertThat(alice.destroyed).isTrue();

		aliceSession.getClass().getMethod("close").invoke(aliceSession);
		bobSession.getClass().getMethod("close").invoke(bobSession);
		assertThat(replacement.destroyed).isTrue();
		assertThat(bob.destroyed).isTrue();
	}

	private static Object newState() throws Exception {
		return Class.forName("org.eclipse.rdf4j.workbench.security.WorkbenchSessionState")
				.getConstructor()
				.newInstance();
	}

	private static final class RecordingServlet extends WorkbenchServlet {
		private boolean destroyed;

		@Override
		public void destroy() {
			destroyed = true;
		}
	}
}
